#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 08: sign in with Telegram, live. Applies the login migration, deploys
# the `api` Edge Function with its secrets, publishes site/ on GitHub Pages,
# registers the Pages domain with BotFather, and has the owner log in.
# Re-run any time; pass `rotate` to replace the session secret (signs everyone out).

cd "$(git rev-parse --show-toplevel)"

TOTAL_STAGES=6
MIGRATION=supabase/migrations/20261015000000_login.sql

# The prompts need a keyboard; without one every read comes back empty.
if [[ ! -t 0 ]]; then
  echo "Run this in a terminal window (not through Claude Code's ! prefix): scripts/sign_in.sh" >&2
  exit 1
fi
set -a; [[ -f "$ENV_FILE" ]] && . "./$ENV_FILE"; set +a
REF=$(printf '%s' "${SUPABASE_URL:-}" | sed -E 's#https://([a-z0-9]+)\.supabase\.co.*#\1#')
API="$SUPABASE_URL/functions/v1/api"
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
SITE="https://${REPO%%/*}.github.io/${REPO#*/}/"

# rpc_status FN JSON: the HTTP status of calling a SQL function through the REST API.
rpc_status() {
  curl -s -o /dev/null -w '%{http_code}' -X POST "$SUPABASE_URL/rest/v1/rpc/$1" \
    -H "apikey: $SUPABASE_SERVICE_KEY" -H "Authorization: Bearer $SUPABASE_SERVICE_KEY" \
    -H 'Content-Type: application/json' -d "$2"
}

banner "Tennis notifier: sign in with Telegram"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
[[ -n "${SUPABASE_URL:-}" && -n "${SUPABASE_SERVICE_KEY:-}" && -n "${TELEGRAM_BOT_TOKEN:-}" ]] \
  || { warn "$ENV_FILE is missing SUPABASE_URL, SUPABASE_SERVICE_KEY or TELEGRAM_BOT_TOKEN. Run scripts/provision.sh first."; exit 1; }
git check-ignore -q "$ENV_FILE" || { warn "$ENV_FILE isn't git-ignored, and this repo is public. Stopping."; exit 1; }
command -v npx >/dev/null 2>&1 || { warn "npx (Node.js) is needed for the Supabase CLI: brew install node"; exit 1; }
[[ -n "$REPO" ]] || { warn "gh isn't signed in: run gh auth login, then re-run this wizard."; exit 1; }
note "Supabase project $REF, repo $REPO, site $SITE"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: apply the login migration"
if [[ "$(rpc_status member_state '{"member_id":0}')" == 200 ]]; then
  note "Already applied: member_state answers."
else
  pbcopy < "$MIGRATION" 2>/dev/null && note "Copied $MIGRATION to the clipboard." \
    || note "Copy the contents of $MIGRATION."
  open_url "https://supabase.com/dashboard/project/$REF/sql/new"
  step "Paste it into the SQL editor and click Run. Expect 'Success. No rows returned'."
  pause "Done? Press Enter"
  until [[ "$(rpc_status member_state '{"member_id":0}')" == 200 ]]; do
    warn "member_state doesn't answer yet. The REST API can take a few seconds to notice."
    pause "Press Enter to check again"
  done
  note "Applied: member_state answers."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: deploy the api Edge Function"
if [[ -z "${SESSION_SECRET:-}" || "${1:-}" == rotate ]]; then
  SESSION_SECRET=$(openssl rand -base64 32 | tr -d '\n')
  write_env SESSION_SECRET "$SESSION_SECRET"
  note "A new session secret: anyone signed in will have to log in again."
else
  note "Keeping the session secret in $ENV_FILE (run with 'rotate' to replace it)."
fi
if [[ -z "${SUPABASE_ACCESS_TOKEN:-}" ]] && ! npx -y supabase projects list >/dev/null 2>&1; then
  say "The Supabase CLI needs you to log in once; a browser window opens."
  npx -y supabase login
fi
secrets=$(mktemp); trap 'rm -f "$secrets"' EXIT
printf 'TELEGRAM_BOT_TOKEN=%s\nSESSION_SECRET=%s\n' "$TELEGRAM_BOT_TOKEN" "$SESSION_SECRET" > "$secrets"
npx -y supabase secrets set --project-ref "$REF" --env-file "$secrets"
rm -f "$secrets"
npx -y supabase functions deploy api --project-ref "$REF" --no-verify-jwt
reply=$(curl -s -w ' %{http_code}' -X POST "$API/login" -d '{}')
if [[ "$reply" == *'"bad_login"'*' 401' ]]; then
  note "The function answers: an unsigned login is refused, as it should be."
else
  warn "Unexpected answer from $API/login: $reply"
  warn "Check the function's logs in the Supabase dashboard, then re-run."
  exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub Pages: publish the site"
git fetch -q origin
if ! git cat-file -e origin/main:site/index.html 2>/dev/null; then
  warn "site/ isn't on GitHub yet. Push main (git push), then re-run this wizard."
  exit 1
fi
if gh api "repos/$REPO/pages" >/dev/null 2>&1; then
  gh api -X PUT "repos/$REPO/pages" -f build_type=workflow >/dev/null
else
  gh api -X POST "repos/$REPO/pages" -f build_type=workflow >/dev/null
fi
note "Pages deploys from GitHub Actions."
last_run() { gh run list --workflow pages.yml --event workflow_dispatch --limit 1 --json databaseId -q '.[0].databaseId // ""'; }
before=$(last_run)
gh workflow run pages.yml --ref main
say "Deploying (about a minute)…"
run=$before
until [[ -n "$run" && "$run" != "$before" ]]; do sleep 3; run=$(last_run); done
gh run watch "$run" --exit-status >/dev/null \
  && note "Deployed: $SITE" || { warn "The pages run failed: gh run view $run"; exit 1; }
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "BotFather: allow logins from the site's domain"
say "Telegram only shows its login for domains registered with the bot."
open_url "https://t.me/BotFather"
step "Send /setdomain and pick @${TELEGRAM_BOT_USERNAME:-your bot}."
step "Send exactly:  ${REPO%%/*}.github.io"
step "BotFather replies 'Success! Domain updated.'"
pause "Done? Press Enter"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Log in as the owner"
open_url "$SITE"
step "Click 'Log in with Telegram' and confirm in the popup, allowing the bot to message you."
step "Expect 'You're in, <your name>', and your name and @handle under the avatar menu."
step "Log out, then log in again from another Telegram account if you have one: it"
step "should get 'This one's invite-only'."
pause "Done? Press Enter"

finish
note "The owner's name and username are refreshed at every login."
